    fn build_create_table(&self, name: String, columns: Vec<ast::Column>) -> Result<Plan> {
        let mut cols = Vec::new();
        let mut primary_key_index = None;
        let mut primary_key_count = 0;

        for (i, col) in columns.into_iter().enumerate() {
            if col.primary_key {
                primary_key_count += 1;
                primary_key_index = Some(i);
            }
            cols.push(Column {
                name: col.name,
                datatype: col.datatype,
                nullable: col.nullable.unwrap_or(false),
                default: col.default.map(|e| Planner::build_expression(e, &Scope::new())?).ok(),
                unique: col.unique,
                index: col.index,
                references: col.references,
            });
        }

        if primary_key_count == 0 {
            return Err(errinput!("table must have a primary key"));
        }
